// Rendering for this feature. State changes are handled by app.js and the domain models.
// Sheets preserve context and keep the separate tab bar available.
function openModal(type,extra={}){if(EntryFlow.stage(account,state.profile)!=='app'){render();return;}if(modal)persistDraft();else lastFocus=document.activeElement;modal={type,...extra};app.inert=true;document.body.style.overflow='hidden';renderModal(true);}
function captureProfileFields(){if(modal?.type!=='onboarding')return;modalRoot.querySelectorAll('[data-profile-field]').forEach(input=>{modal.draft[input.dataset.profileField]=['age','height'].includes(input.dataset.profileField)?(input.value===''?'':Number(input.value)):input.value;});modal.draft.billPreferences=modal.draft.billPreferences.filter(id=>Dating.billChoices(modal.draft).some(c=>c.id===id));}
function persistDraft(){if(!modal)return;if(modal.type==='onboarding'){captureProfileFields();state.drafts.profile={step:modal.step,draft:clone(modal.draft)};showSaved(save());}if(modal.type==='proposal'){captureProposalFields();state.drafts.proposal={sessionId:state.session?.id,baseRevision:modal.baseRevision,draft:clone(modal.draft)};showSaved(save());}}
function showSaved(ok){const el=modalRoot.querySelector('[data-saved-status]');if(el){el.textContent=ok?'✓ Draft saved':'Not saved';el.classList.toggle('saved-status',ok);}}
function closeModal(redraw=true){if(modal?.required&&!state.profile.complete&&account.user)return;persistDraft();modal=null;modalRoot.innerHTML='';app.inert=false;document.body.style.overflow='';if(redraw)render();if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});else document.querySelector('.page-title')?.focus({preventScroll:true});}
function dismissModal(){const closing=modalRoot.querySelector('.dialog');PremiumMotion.dismiss(closing,()=>{if(modalRoot.querySelector('.dialog')===closing)closeModal();});}
function dialogFooter(backLabel,backAction,nextLabel,nextAction,disabled=false,extra=''){return`<div class="dialog-footer">${button(backLabel,backAction,'secondary','','')}${button(nextLabel,nextAction,'primary',`${disabled?'disabled':''} ${extra}`)}</div>`;}
function dialogHeading(kicker,title,description=''){const tag=modal?.required?'h1':'h2';return`<div class="dialog-heading">${kicker?`<p class="eyebrow">${kicker}</p>`:''}<${tag} id="dialog-title" tabindex="-1">${title}</${tag}>${description?`<p>${description}</p>`:''}</div>`;}
function wizardProgress(step,labels){return`<ol class="wizard-progress" aria-label="Step ${step+1} of ${labels.length}">${labels.map((label,i)=>`<li class="${i===step?'current':i<step?'done':''}" ${i===step?'aria-current="step"':''}><span>${i<step?icon('check'):i+1}</span><span class="step-label">${label}</span></li>`).join('')}</ol>`;}
function renderModal(resetScroll=false){
  if(!modal)return;
  if(modal.required){
    const active=document.activeElement,focusId=modalRoot.contains(active)?active.id:null,data=modalRoot.contains(active)&&active.dataset.action?{...active.dataset}:null;
    const first=!modalRoot.querySelector('.setup-page');
    modalRoot.innerHTML=`<main class="setup-page" aria-labelledby="dialog-title">${entryHeader()}<div class="setup-status"><span>Your private profile</span><span data-saved-status>Draft kept in this browser</span></div>${onboardingModal()}</main>`;
    const target=focusId?modalRoot.querySelector('#'+CSS.escape(focusId)):data?[...modalRoot.querySelectorAll('[data-action]')].find(node=>node.dataset.action===data.action&&node.dataset.group===data.group&&node.dataset.value===data.value):null;
    if(resetScroll||first){window.scrollTo({top:0,behavior:'instant'});modalRoot.querySelector('#dialog-title')?.focus({preventScroll:true});PremiumMotion.enter(modalRoot.querySelector('.dialog-heading'));}else target?.focus({preventScroll:true});
    return;
  }
  const active=document.activeElement,oldDialog=modalRoot.querySelector('.dialog'),oldTop=resetScroll?0:oldDialog?.scrollTop||0,focusId=modalRoot.contains(active)?active.id:null,focusData=modalRoot.contains(active)&&active.dataset.action?{...active.dataset}:null;
  const views={verify:verifyModal,unlock:unlockModal,help:helpModal,onboarding:onboardingModal,proposal:proposalModal,safety:safetyModal,cancel:cancelModal,'plan-preview':planPreviewModal,reset:resetModal,report:reportModal,'report-receipt':reportReceiptModal,notifications:notificationsModal,copy:copyModal,why:whyModal};
  const body=views[modal.type]();
  modalRoot.innerHTML=`<div class="dialog-backdrop"><section class="dialog ${['onboarding','proposal'].includes(modal.type)?'wizard-dialog':'small-dialog'}" role="dialog" aria-modal="false" aria-labelledby="dialog-title" tabindex="-1"><div class="drag-zone" aria-hidden="true"><span></span></div><div class="dialog-toolbar"><span data-saved-status>${['onboarding','proposal'].includes(modal.type)?'Draft kept in this browser':'blinddate'}</span>${['onboarding','proposal'].includes(modal.type)?`<button class="icon-button done-circle" data-action="close-modal" aria-label="Save and close">${icon('check')}</button>`:`<button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button>`}</div>${body}</section></div>`;
  const dialog=modalRoot.querySelector('.dialog');dialog.scrollTop=oldTop;
  const target=resetScroll?null:focusId?modalRoot.querySelector('#'+CSS.escape(focusId)):focusData?[...modalRoot.querySelectorAll('[data-action]')].find(el=>el.dataset.action===focusData.action&&el.dataset.value===focusData.value&&el.dataset.group===focusData.group):null;
  (target||modalRoot.querySelector('#dialog-title')||dialog).focus({preventScroll:true});PremiumMotion.sheet(dialog,()=>{if(modalRoot.querySelector('.dialog')===dialog)closeModal();},resetScroll);if(modal.type==='report-receipt')PremiumMotion.pop(dialog.querySelector('.receipt-check'));
}
function fieldError(key){return modal.errors?.[key]?`<p class="field-error" id="error-${key}" role="alert">${esc(modal.errors[key])}</p>`:'';}
function inputField(label,key,type='text',extra=''){return`<div class="field"><label for="profile-${key}">${label}</label><input class="input" id="profile-${key}" data-profile-field="${key}" type="${type}" value="${esc(modal.draft[key])}" ${extra} ${modal.errors?.[key]?'aria-invalid="true" aria-describedby="error-'+key+'"':''}>${fieldError(key)}</div>`;}
function selectField(label,key,options,optional=false){return`<div class="field"><label for="profile-${key}">${label}</label><select class="input" id="profile-${key}" data-profile-field="${key}" ${modal.errors?.[key]?'aria-invalid="true" aria-describedby="error-'+key+'"':''}>${!optional?'<option value="">Choose an answer</option>':''}${options.map(v=>`<option ${modal.draft[key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select>${fieldError(key)}</div>`;}
function choices(options,selected,group,multi=false){return`<div class="choice-group" role="group" aria-label="${group}" tabindex="-1" id="profile-${group}">${options.map(value=>`<button class="choice ${(multi?selected.includes(value):selected===value)?'selected':''}" aria-pressed="${multi?selected.includes(value):selected===value}" data-action="profile-choice" data-group="${group}" data-value="${esc(value)}" ${multi?'data-multi="true"':''}>${esc(value)}${(multi?selected.includes(value):selected===value)?icon('check'):''}</button>`).join('')}</div>${fieldError(group)}`;}
function onboardingModal(){
  const p=modal.draft,step=modal.step;let fields='';
  if(step===0)fields=`${dialogHeading('About you · 1 of 5','Hey, you.','Start with your own story. The questions about your type come afterward.')}${photoSlots(p)}<div class="field-grid">${inputField('First name','name','text','maxlength="40" autocomplete="given-name"')}${inputField('Age · 18 or older','age','number','min="18" max="100" inputmode="numeric"')}</div>${selectField('I describe myself as','gender',Dating.genders,true)}${selectField('Education','education',Dating.educationOptions)}${inputField('Work or study · optional','work','text','maxlength="80"')}${inputField('Height in cm · optional','height','number','min="120" max="230" inputmode="numeric" placeholder="e.g. 175"')}<p class="caption">Height is only used if someone asks for taller or shorter. Your full profile stays hidden.</p>`;
  if(step===1)fields=`${dialogHeading('About you · 2 of 5','Where you’re from, what you believe.','Only languages are required. The rest is optional, used only for matching, and never shown on an introduction.')}<div class="field"><span class="field-label">Languages I speak</span>${choices(Dating.languages,p.languages,'languages',true)}</div>${selectField('Religion or faith · optional','religion',Dating.religions,true)}${selectField('Ethnicity · optional','ethnicity',Dating.ethnicities,true)}${selectField('Zodiac · optional, just for fun','zodiac',Dating.zodiacs,true)}<p class="caption">If you prefer not to say, you won’t be introduced to people who require a specific answer.</p>`;
  if(step===2)fields=`${dialogHeading('About you · 3 of 5','What’s your energy?','Your answers describe you. Later, you’ll tell us what you like in someone else.')}${selectField('My social energy','energy',Dating.energies)}${selectField('My usual activity level','activity',Dating.activities)}${selectField('How often I work out','workout',Dating.workouts)}${selectField('How I feel about animals','pets',Dating.pets)}${selectField('Smoking','selfSmoking',['Non-smoker','Smoker'])}${selectField('Drinking','drinking',Dating.drinking)}${selectField('Dietary preferences','diet',Dating.diets,true)}`;
  if(step===3)fields=`${dialogHeading('About you · 4 of 5','The little things that make you, you.','Choose at least one interest and quality. These help find common ground.')}<div class="field"><span class="field-label">Things I enjoy</span>${choices(interestOptions,p.interests,'interests',true)}</div><div class="field"><span class="field-label">Qualities I value</span>${choices(valueOptions,p.values,'values',true)}</div>${selectField('My relationship intentions','intent',Dating.intents,true)}${selectField('Family plans','familyPlans',Dating.familyPlans)}<details class="optional-details"><summary>My political views <span>Optional</span></summary>${selectField('My view','ownPolitics',Dating.politics,true)}<p class="caption">Used only if you choose similar views in your partner preferences.</p></details><details class="optional-details"><summary>How I connect <span>Optional</span></summary>${selectField('Communication style','communication',Dating.communication,true)}${selectField('Love style','loveStyle',Dating.loveStyles,true)}<p class="caption">Shared styles help rank introductions. They never rule anyone out.</p></details>`;
  if(step===4)fields=`${dialogHeading('About you · 5 of 5','Keep the bill comfortable.','Choose every arrangement you’d accept. We’ll only introduce people with a compatible option.')}<div class="bill-choice-list" id="profile-billPreferences" tabindex="-1" role="group" aria-label="Bill arrangements">${Dating.billChoices(p).map(c=>`<button class="answer-option ${p.billPreferences.includes(c.id)?'selected':''}" data-action="profile-choice" data-group="billPreferences" data-value="${c.id}" data-multi="true" aria-pressed="${p.billPreferences.includes(c.id)}"><span><strong>${c.title}</strong><span>${c.detail}</span></span><span class="answer-check">${p.billPreferences.includes(c.id)?icon('check'):''}</span></button>`).join('')}</div>${fieldError('billPreferences')}<div class="info-note">${icon('coffee')}“Each pays for their own” means your own food and drinks, rather than half of a shared total. Every proposed date shows the exact agreement.</div><p class="caption bill-disclaimer">This is a comfort preference, not a payment. You’ll review it again before confirming a date.</p>`;
  return`${wizardProgress(step,['You','Background','Vibe','Interests','Bill'])}<div class="dialog-content">${fields}</div>${dialogFooter(step?'Back':modal.required?'Log out':'Save & close',step?'onboarding-back':modal.required?'auth-log-out':'close-modal',step===Dating.profileSteps-1?'Save my profile':'Continue','onboarding-next',!!modal.photoPending)}`;
}
function startProfile(billOnly=false,requestedStep){const saved=state.drafts.profile,step=Number(requestedStep);openModal('onboarding',{step:billOnly&&state.profile.complete?Dating.profileSteps-1:Number.isInteger(step)&&step>=0&&step<Dating.profileSteps?step:saved?.step||0,draft:{...clone(saved?.draft||state.profile),verification:state.profile.verification},errors:{}});}
function captureProposalFields(){if(modal?.type!=='proposal')return;modalRoot.querySelectorAll('[data-proposal-field]').forEach(input=>modal.draft[input.dataset.proposalField]=input.value);}
function proposalModal(){const c=state.session.person,p=modal.draft,places=venues.filter(v=>Dating.venueFits(v,state.profile)&&Dating.venueFits(v,c)),bills=Dating.billOptions(state.profile,c);return`<div class="dialog-content">${dialogHeading('A plan to agree on','Offer a little possibility.','This offer is for this date only. It won’t change your saved availability.')}<div class="field"><label for="proposal-date">Day · Vancouver time</label><input class="input" id="proposal-date" type="date" min="${Dating.dateOffset(1)}" max="${Dating.dateOffset(60)}" value="${esc(p.date)}" data-proposal-field="date"></div><div class="field"><label for="proposal-time">Start time · allow one hour</label><input class="input" id="proposal-time" type="time" step="900" value="${esc(p.time)}" data-proposal-field="time"></div><div class="field"><label for="proposal-venueId">Place</label><select class="input" id="proposal-venueId" data-proposal-field="venueId">${places.map(v=>`<option value="${v.id}" ${p.venueId===v.id?'selected':''}>${esc(v.name)} · ~C$${v.price}/person</option>`).join('')}</select></div><div class="field"><label for="proposal-billMode">Agreed bill option</label><select class="input" id="proposal-billMode" data-proposal-field="billMode">${bills.map(id=>`<option value="${id}" ${p.billMode===id?'selected':''}>${esc(Dating.billText(id))}</option>`).join('')}</select></div>${!bills.length?`<div class="inline-alert">Your current bill preferences don’t overlap. ${button('Review my bill preferences','profile-bill','secondary','','')}</div>`:''}<div class="field"><label for="proposal-note">A note · optional</label><select class="input" id="proposal-note" data-proposal-field="note">${Trust.notePresets.map(n=>`<option value="${esc(n)}" ${p.note===n?'selected':''}>${n?esc(n):'No note'}</option>`).join('')}</select><p class="caption">Notes come from a list until after your date, so contact details can’t be shared early.</p></div>${modal.errors?.plan?`<p class="field-error" role="alert">${esc(modal.errors.plan)}</p>`:''}<p class="caption">Sending records your acceptance of this offer. The other person still needs to agree. Notifications and replies are simulated.</p></div>${dialogFooter('Save & close','close-modal','Send demo proposal','send-proposal',!bills.length||!places.length)}`;}
function openProposal(){
  const s=state.session;if(!s?.person)return;
  const base=s.proposal||s.suggested||Dating.planFromChoice(s.availability,state.profile,s.person)||Dating.planFromChoice(s.availability,state.profile,s.person,true)||{date:Dating.dateOffset(3),time:'18:00',venueId:venues.find(v=>Dating.venueFits(v,state.profile)&&Dating.venueFits(v,s.person))?.id||'',billMode:Dating.billOptions(state.profile,s.person)[0]||''};
  const saved=state.drafts.proposal;const revision=s.proposal?.revision||0;
  const draft=clone(saved?.sessionId===s.id&&saved.baseRevision===revision?saved.draft:{...base,note:''});if(!Trust.notePresets.includes(draft.note))draft.note='';
  openModal('proposal',{baseRevision:revision,draft,errors:{}});
}
function whyModal(){const c=state.session?.person;return`<div class="dialog-content">${dialogHeading('A little common ground','Why this introduction?','The prototype compares actual answers, not a compatibility percentage.')}<div class="reason-list"><div>${icon('heart')}<div><h3>Personality and intentions</h3><p>Your selected energy, pace, pets, age, distance and lifestyle boundaries are respected.</p></div></div><div>${icon('coffee')}<div><h3>Bill comfort</h3><p>${c?Dating.billOptions(state.profile,c).map(Dating.billText).map(esc).join(' · '):'Both people need at least one compatible option.'}</p></div></div><div>${icon('calendar')}<div><h3>A plan comes next</h3><p>Shared time and place are prioritized. Otherwise you can propose a change or rematch.</p></div></div></div><p class="caption">Sample profiles only. Attraction is something you discover in person.</p></div>${dialogFooter('Close','close-modal','Review our plan','view-introduction')}`;}
function notificationsModal(){const notices=[...state.inbox].sort((a,b)=>b.at-a.at);return`<div class="dialog-content">${dialogHeading('Your local demo inbox','Notifications',notices.length?'Updates from your saved introduction and simulated replies.':'You’re all caught up.')}<div class="group-card">${notices.map(n=>row(esc(n.title),esc(n.detail),'bell','open-notice',`data-value="${esc(n.id)}"`,!n.read?'violet':'')).join('')}${state.drafts.profile?row('Your profile draft is saved','Continue step '+(state.drafts.profile.step+1)+' of '+Dating.profileSteps,'edit','onboarding'):''}</div>${!notices.length&&!state.drafts.profile?'<div class="notification-empty">'+icon('bell')+'<p>Your date discussions will appear here. No real messages are sent.</p></div>':''}</div>${dialogFooter('Back','close-modal','Done','close-modal')}`;}
function copyModal(){return`<div class="dialog-content">${dialogHeading('Copy date details','Your plan, in one place.','Select and copy the details below.')}<textarea class="input copy-fallback" readonly aria-label="Date details">${esc(modal.details)}</textarea></div>${dialogFooter('Back','close-modal','Done','close-modal')}`;}

function safetyModal() {
  return `<div class="dialog-content">${dialogHeading('SAFETY & SUPPORT', 'You’re always in control.', 'A date is an invitation. You decide what happens next.')}<ul class="safety-list"><li>Meet in a public, staffed venue and arrange your own way home.</li><li>Share the date details with someone you trust.</li><li>Leave whenever you want. There’s no fee for ending a date early.</li><li>Safety concerns and emergencies are exempt from the example cancellation fee.</li></ul><div class="info-note">${icon('shield')}This prototype has no live support, identity verification or monitored reports. Preferences are saved in this browser.</div></div>${dialogFooter('Preview a report','report',state.booking?'Copy date details':'Done',state.booking?'share':'close-modal')}`;
}
function cancelModal() {
  const fee = cancellationFee(state.booking, modal.reason);
  return `<div class="dialog-content">${dialogHeading('CANCEL YOUR DATE', 'Plans change. That’s okay.', 'Review the cancellation details. There’s no charge in this prototype.')}<div class="field"><label for="cancel-reason">Reason for cancelling</label><select class="input" id="cancel-reason"><option value="">Choose a reason</option>${['Plans changed','Safety concern','Emergency','I’d prefer another introduction'].map(reason=>`<option ${modal.reason===reason?'selected':''}>${reason}</option>`).join('')}</select></div><div class="fee-display"><span>Example cancellation fee</span><strong>C$${fee}</strong></div><p class="body-small">${fee===0?'You’re before the deadline, or a safety/emergency exception applies.':'You’re inside the 24-hour deadline. In a live service, you could appeal this fee.'} Your introduction credit is restored.</p></div>${dialogFooter('Keep date','close-modal','Cancel demo date','confirm-cancel',!modal.reason)}`;
}
function planPreviewModal() { return `<div class="dialog-content">${dialogHeading('MEMBERSHIP PREVIEW', state.plan==='annual'?'Yearly membership.':'Monthly membership.', state.plan==='annual'?'C$299.99 upfront per year, before tax.':'C$29.99 per month, before tax.')}<ul class="feature-list"><li>${icon('check')} Two arranged-date credits each month</li><li>${icon('check')} Food and drinks paid separately</li><li>${icon('check')} Ratings, reviews and show-up records included</li><li>${icon('check')} No payment or subscription in this demo</li></ul></div>${dialogFooter('Go back','close-modal','Start demo membership','confirm-plan')}`; }
function verifyModal(){return`<div class="dialog-content">${dialogHeading('Verification demo','Try the verified badge.','Use two sample images to preview the flow. No identity check happens here. In a live app, your date would only see a Verified badge.')}<div class="field"><span class="field-label">1. Government ID</span><label class="upload-row ${modal.idDone?'done':''}"><input type="file" accept="image/*" data-verify="idDone" aria-label="Add a photo of your ID">${icon(modal.idDone?'check':'plus')}<span>${modal.idDone?'ID added':'Add a photo of your ID'}</span></label></div><div class="field"><span class="field-label">2. Selfie</span><label class="upload-row ${modal.selfieDone?'done':''}"><input type="file" accept="image/*" capture="user" data-verify="selfieDone" aria-label="Take a selfie">${icon(modal.selfieDone?'check':'plus')}<span>${modal.selfieDone?'Selfie added':'Take a selfie'}</span></label></div><div class="info-note">${icon('lock')}Demo: these images are never read, saved or uploaded, and no real check happens. A live app needs a verification provider and a clear data-retention policy.</div></div>${dialogFooter('Not now','close-modal','Preview verified badge','verify-submit',!(modal.idDone&&modal.selfieDone))}`;}
function unlockModal(){return`<div class="dialog-content">${dialogHeading('Before you meet','See their record.','Rating, show-up record and what past dates said.')}<div class="fee-display"><span>This introduction</span><strong>C$1.99</strong></div><p class="body-small">Included with blinddate+. Demo: no payment is taken.</p></div>${dialogFooter('Not now','close-modal','Unlock for C$1.99','confirm-unlock')}`;}
function helpModal(){return`<div class="dialog-content">${dialogHeading('Safety','You’re not alone.','Choose what you need. Leaving a date early never has a fee.')}<div class="group-card"><a class="list-row" href="tel:911"><span class="row-icon">${icon('warning',true)}</span><span class="row-copy"><strong>Call 911</strong><span>For any emergency</span></span>${icon('chevron')}</a>${row('Ask my trusted contact for help',state.trusted.contact?'Copy a help message, then send it yourself':'Add a trusted contact on the Dates tab first','people','share-trusted')}${row('Report this person','Goes to the safety team (demo: not sent)','flag','report')}</div><p class="caption">Prototype: no live safety team or automatic alerts are connected.</p></div>${dialogFooter('Back','close-modal','I’m safe now','close-modal')}`;}
async function shareTrusted(urgent=false){
  const b=state.booking,t=state.trusted;
  if(!b){toast('Your date details appear here once a date is confirmed.');return;}
  if(!t.contact||Trust.contactErrors(t.contact)||!/[0-9]/.test(t.contact)){
    if(modal)closeModal(false);navigate('dates');
    document.querySelector('#trusted-contact')?.focus();
    document.querySelector('#trusted-contact')?.scrollIntoView({block:'center'});
    toast('Add a valid phone number for your trusted contact first.');return;
  }
  const v=venueById(b.venueId),intro=urgent?'I need help. Please contact me now.':'I’m on a blinddate.';
  const text=`Hi ${t.name||''}, ${intro} ${v.name}, ${v.area}, Vancouver. ${dateLabel(b.timestamp,{weekday:'long',month:'long',day:'numeric'})} at ${timeLabel(b.timestamp)} ${Trust.markerText(b.marker)} ${urgent?'Please check on me as soon as you can.':`If you don’t hear from me by ${timeLabel(b.timestamp+2*3600000)}, please check on me.`}`;
  try{await navigator.clipboard.writeText(text);toast('Message copied. Send it to '+(t.name||'your contact')+'.');}
  catch{openModal('copy',{details:text});}
}
function resetModal() { return `<div class="dialog-content">${dialogHeading('RESET PROTOTYPE', 'Start fresh?', 'This clears this browser’s demo profile, preferences, availability, proposals, inbox, date, theme and plan preview.')}</div>${dialogFooter('Keep my demo','close-modal','Reset demo','confirm-reset')}`; }
function reportModal() { return `<div class="dialog-content">${dialogHeading('REPORT PREVIEW', 'Tell us what happened.', 'This previews a support flow. Reports are not sent or monitored.')}<div class="field"><label for="report-category">What would you like to report?</label><select class="input" id="report-category"><option>Something made me uncomfortable</option><option>A person didn’t attend</option><option>A profile concern</option><option>A venue concern</option></select></div><div class="field"><label for="report-details">Details · optional</label><textarea class="input" id="report-details" placeholder="Use sample information."></textarea></div></div>${dialogFooter('Back','safety','Preview receipt','demo-report')}`; }
function reportReceiptModal() { return `<div class="dialog-content"><span class="receipt-check">${icon('check')}</span>${dialogHeading('PREVIEW COMPLETE', 'Your voice matters.', 'A live report would go to the support team. In this prototype, nothing was sent and report details were not saved.')}${button('Done','close-modal')}</div>`; }
